import java.util.*;

public class Main {
    interface Payment { String pay(int cents); }

    static final class CardPayment implements Payment {
        public String pay(int cents) { return "card:" + cents; }
    }

    static final class WalletPayment implements Payment {
        public String pay(int cents) { return "wallet:" + cents; }
    }

    static final class Logistics {
        String route() { return "standard"; }
    }

    static final class OrderService {
        private final Payment payment;
        private final Logistics logistics;

        OrderService(Payment payment, Logistics logistics) {
            this.payment = payment;
            this.logistics = logistics;
        }

        String checkout() {
            return payment.pay(1299) + " via " + logistics.route();
        }
    }

    static final class BeanDef {
        final String name;
        final Class<?> type;
        final Object instance;
        final boolean primary;

        BeanDef(String name, Class<?> type, Object instance, boolean primary) {
            this.name = name;
            this.type = type;
            this.instance = instance;
            this.primary = primary;
        }
    }

    static final class MiniContainer {
        private final List<BeanDef> beans = new ArrayList<>();

        <T> void register(String name, Class<T> type, T instance) {
            register(name, type, instance, false);
        }

        <T> void register(String name, Class<T> type, T instance, boolean primary) {
            beans.add(new BeanDef(name, type, instance, primary));
        }

        <T> T byType(Class<T> type) {
            List<BeanDef> candidates = candidates(type);
            if (candidates.isEmpty()) {
                throw new IllegalStateException("no bean for " + type.getSimpleName());
            }
            List<BeanDef> primaries = candidates.stream().filter(b -> b.primary).toList();
            if (primaries.size() == 1) {
                return type.cast(primaries.get(0).instance);
            }
            if (candidates.size() == 1) {
                return type.cast(candidates.get(0).instance);
            }
            throw new IllegalStateException("ambiguous: " + names(candidates));
        }

        <T> T byName(String name, Class<T> type) {
            return beans.stream()
                    .filter(b -> b.name.equals(name) && type.isAssignableFrom(b.type))
                    .findFirst()
                    .map(b -> type.cast(b.instance))
                    .orElseThrow(() -> new IllegalStateException("no bean named " + name));
        }

        <T> Map<String, T> allByType(Class<T> type) {
            Map<String, T> result = new LinkedHashMap<>();
            for (BeanDef bean : candidates(type)) {
                result.put(bean.name, type.cast(bean.instance));
            }
            return result;
        }

        private <T> List<BeanDef> candidates(Class<T> type) {
            return beans.stream().filter(b -> type.isAssignableFrom(b.type)).toList();
        }

        private static List<String> names(List<BeanDef> beans) {
            return beans.stream().map(b -> b.name).toList();
        }
    }

    public static void main(String[] args) {
        MiniContainer container = new MiniContainer();
        container.register("cardPay", Payment.class, new CardPayment());
        container.register("walletPay", Payment.class, new WalletPayment());
        container.register("logistics", Logistics.class, new Logistics());

        // 多候选无 primary 时按类型查找抛歧义异常
        try {
            container.byType(Payment.class);
        } catch (IllegalStateException ex) {
            System.out.println("ambiguousPayment=" + ex.getMessage().contains("cardPay"));
        }

        // 按名称消歧等价于 @Qualifier 或 bean name 精确匹配
        OrderService order = new OrderService(
                container.byName("walletPay", Payment.class),
                container.byType(Logistics.class)
        );
        System.out.println("checkout=" + order.checkout());

        // 注册 primary 后，按类型注入能在多候选中选出首选 Bean
        container.register("primaryCard", Payment.class, new CardPayment(), true);
        System.out.println("primary=" + container.byType(Payment.class).pay(88));

        // allByType 等价于集合注入，返回所有类型匹配的候选
        System.out.println("paymentBeans=" + container.allByType(Payment.class).keySet());
    }
}
